registerRefData('nsw-cond-n-2',{"id":2,"pan":null,"ref":"DA-380/2023","address":null,"description":null,"outcome":null,"outcome_raw":null,"outcome_source":null,"determined":null,"notice_url":"https://apps.planningportal.nsw.gov.au/prweb/PRRestService/DocMgmt/v1/PublicDocuments/DATA-WORKATTACH-FILE%20PEC-DPE-EP-WORK%20PPSSWC-348!20241011T035447.654%20GMT","sha256":"549672c54b1d66afe6c166a617d8f521e0a19d080a99bb058dbd5d175746bdd9","pages":19,"layout":"coded","n":194,"fetched_at":"2026-08-16T06:47:45+00:00","file":"n/2.js","source_page":null,"lga":"LIVERPOOL","conditions":[{"label":"A002","code":"A002","number":null,"title":"Approved plans and supporting documentation","text":"Development must be carried out in accordance with the following approved plans and documents, except where the conditions of this\nconsent expressly require otherwise.\nApproved plans\nPlan title Revision Plan number Drawn by Date of plan\nCover Page C DA000 Morfosis Architects Pty Ltd 31/07/24\nSite Roof Plan C DA200 Morfosis Architects Pty Ltd 31/07/24\nBasement Level 01 Plan C DA201 Morfosis Architects Pty Ltd 31/07/24\nBasement Level 02 Plan B DA202 Morfosis Architects Pty Ltd 18/03/24\nGround Floor Plan C DA203 Morfosis Architects Pty Ltd 31/07/24\nLevel 01 Floor Plan C DA204 Morfosis Architects Pty Ltd 31/07/24\nLevel 02 Floor Plan C DA205 Morfosis Architects Pty Ltd 31/07/24\nLevel 03 Floor Plan C DA206 Morfosis Architects Pty Ltd 31/07/24\nLevel 04 Floor Plan C DA207 Morfosis Architects Pty Ltd 31/07/24\nLevel 05 Floor Plan C DA208 Morfosis Architects Pty Ltd 31/07/24\nLevel 06 Floor Plan C DA209 Morfosis Architects Pty Ltd 31/07/24\nRoof Plan C DA210 Morfosis Architects Pty Ltd 31/07/24\nDetailed Plan GF LVL C DA211 Morfosis Architects Pty Ltd 31/07/24\nDetailed Plan LVL 01 C DA212 Morfosis Architects Pty Ltd 31/07/24\nDetailed Plan LVL 02 C DA213 Morfosis Architects Pty Ltd 31/07/24\nDetailed Plan LVL 03 C DA214 Morfosis Architects Pty Ltd 31/07/24\nDetailed Plan LVL 04 C DA215 Morfosis Architects Pty Ltd 31/07/24\nDetailed Plan LVL 05 C DA216 Morfosis Architects Pty Ltd 31/07/24\nDetailed Plan LVL 06 C DA217 Morfosis Architects Pty Ltd 31/07/24\nDetailed Plan Roof C DA218 Morfosis Architects Pty Ltd 31/07/24\nAdaptable Unit Type A Pre Adaption C DA221 Morfosis Architects Pty Ltd 31/07/24\nAdaptable Unit Type A Post Adaption C DA222 Morfosis Architects Pty Ltd 31/07/24\nAdaptable Unit Type B Pre Adaption C DA223 Morfosis Architects Pty Ltd 31/07/24\nAdaptable Unit Type B Post Adaption C DA224 Morfosis Architects Pty Ltd 31/07/24\nTypical Facade Detail 1 (Roof) C DA230 Morfosis Architects Pty Ltd 31/07/24\nTypical Facade Detail 2 (Balcony) C DA231 Morfosis Architects Pty Ltd 31/07/24\nFront ElevationS & External Finishes Schedule C DA300 Morfosis Architects Pty Ltd 31/07/24\nRear ElevationN C DA301 Morfosis Architects Pty Ltd 31/07/24\nSide ElevationE C DA302 Morfosis Architects Pty Ltd 31/07/24\nSide ElevationW C DA303 Morfosis Architects Pty Ltd 31/07/24\nSections C DA350 Morfosis Architects Pty Ltd 31/07/24\nRamp Sections C DA352 Morfosis Architects Pty Ltd 31/07/24\nDemolition Plan A DP 01/01 Morfosis Architects Pty Ltd 14/12/22\nErosion and Sediment Control Plan and Details B D06 Loka Consulting Engineers Pty Ltd 24/11/22\nLandscape Plans\nDocument title Revision Prepared by Date of document\nLandscape Plan Ground Floor B Greenland Design Landscape Architects 22/03/24\nLandscape Plan Level 1 B Greenland Design Landscape Architects 22/03/24\nLandscape Plan Level 2 B Greenland Design Landscape Architects 22/03/24\nLandscape Plan Level 3 B Greenland Design Landscape Architects 22/03/24\nLandscape Plan Level 5 B Greenland Design Landscape Architects 22/03/24\nLandscape Plan Roof Terrace B Greenland Design Landscape Architects 22/03/24\nLandscape Details & Specifications B Greenland Design Landscape Architects 22/03/24\nApproved documents\nDocument title Reference Prepared by Date of document\nWaste Management Plan 22NL062 WMP3 Loka Consulting Engineers Pty Ltd 15/08/24\nBASIX Certificate 1764140M Loka Consulting Engineers Pty Ltd 12/09/24\nNatHERS Certificate #HROB9FPK01 Loka Consulting Engineers Pty Ltd 11/09/24\nSEPP 65 Design Verification Statement REV A Morfosis Architects Pty Ltd 31/07/24\nAccess Report 22NL062A2 Loka Consulting Engineers Pty Ltd 21/08/24\nTraffic Management Report 22NL062T2 Loka Consulting Engineers Pty Ltd 10/02/23\nTraffic Assessment Proposed Residential Flat Building 23.24.020 Traffic Solutions Pty Ltd 22/03/24\nGeotechnical Investigation 20192/1AA Geotechnique Pty Ltd 06/07/22\nArboricultural Impact Assessment and Tree Management Plan Version 1 Horticultural Management Services 25/06/22\nIn the event of any inconsistency between the approved plans and documents, the approved <Plans / Documents> prevail.\nIn the event of any inconsistency with the approved plans and a condition of this consent, the condition prevails.","stage":"general","stage_basis":"heading","page":2},{"label":"A004","code":"A004","number":null,"title":"Payment of development contributions","text":"Payment of section 7.11 contributions Liverpool Contributions Plan 2018 Established Areas\nBefore the issue of a construction certificate, the applicant must pay the following contributions to Council for:\n2 General Condition","stage":"general","stage_basis":"heading","page":2},{"label":"A015","code":"A015","number":null,"title":"Endeavour Energy Requirements","text":"The development shall comply in full with all requirements outlined within the correspondence prepared by Endeavour Energy dated\n10/08/2023 and all conditions contained therein.","stage":"general","stage_basis":"heading","page":3},{"label":"A018","code":"A018","number":null,"title":"Fulfilment of BASIX commitments","text":"It is a condition of a development consent for the following that each commitment listed in a relevant BASIX certificate is fulfilled-\nBASIX development,\nBASIX optional development, if the development application was accompanied by a BASIX certificate.","stage":"general","stage_basis":"heading","page":3},{"label":"A025","code":"A025","number":null,"title":"Comply with EP&A Act","text":"The requirements and provisions of the Environmental Planning & Assessment Act 1979 and Environmental Planning & Assessment Regulation 2021, must be fully complied\nwith at all times.\nFailure to comply with these legislative requirements is an offence and may result in the commencement of legal proceedings, issuing of ‘onthespot’ penalty infringements or\nservice of a notice and order by Council.","stage":"general","stage_basis":"heading","page":3},{"label":"A040","code":"A040","number":null,"title":"Compliance with the Building Code of Australia","text":"It is a condition of a development consent for development that involves building work that the work must be carried out in accordance with the requirements of the\nBuilding Code of Australia.\nIt is a condition of a development consent for development that involves residential building work for which a contract of insurance is required under the Home Building Act\n1989, Part 6 that a contract of insurance is in force before building work authorised to be carried out by the consent commences.\nIt is a condition of a development consent for a temporary structure used as an entertainment venue that the temporary structure must comply with Part B1 and NSW\nPart H102 in Volume 1 of the Building Code of Australia.\nIn subsection (1), a reference to the Building Code of Australia is a reference to the Building Code of Australia as in force on the day on which the application for the\nconstruction certificate was made.\nIn subsection (3), a reference to the Building Code of Australia is a reference to the Building Code of Australia as in force on the day on which the application for\ndevelopment consent was made.\nThis section does not apply-\nto the extent to which an exemption from a provision of the Building Code of Australia or a fire safety standard is in force under the Environmental Planning and\nAssessment (Development Certification and Fire Safety) Regulation 2021, or\nto the erection of a temporary building, other than a temporary structure to which subsection (3) applies.","stage":"general","stage_basis":"heading","page":3},{"label":"A050","code":"A050","number":null,"title":"Works at no cost to Council","text":"All roadworks, drainage works and dedications, required to effect the consented development shall be undertaken at no cost to Liverpool City Council.","stage":"general","stage_basis":"heading","page":3},{"label":"A053","code":"A053","number":null,"title":"Residential flat buildings-social housing providers, public authorities and joint ventures","text":"This section applies to development permitted under State Environmental Planning Policy (Housing) 2021, Chapter 2, Part\n2, Division 5, other than-\ndevelopment on land owned by the Land and Housing Corporation, or\na development application made by a public authority.\nIt is a condition of the development consent that before the issue of an occupation certificate for the development-\na restriction must be registered, in accordance with the Conveyancing Act 1919, section 88E, against the title of the property relating to the development, which\nwill ensure the requirements in subsection (3)(a) and (b) are met, and\nevidence of an agreement with a registered community housing provider for the management of the residential flat building must be given to the Registrar of\nCommunity Housing, including the name of the registered community housing provider, and\nevidence that the requirements in paragraph (a) and (b) have been met must be given to the consent authority.\nIt is a condition of the development consent that during the relevant period-\n50% of the dwellings to which the development consent relates must be used for affordable housing (the affordable housing dwellings), and\nthe affordable housing dwellings must be managed by a registered community housing provider, and\nnotice of a change in the registered community housing provider who manages the affordable housing dwellings must be given to the Registrar of Community\nHousing and the consent authority no later than 3 months after the change, and\nthe registered community housing provider who manages the affordable housing dwellings must apply the Affordable Housing Guidelines.\nIn this section-\nrelevant period means a period of 15 years commencing on the day on which an occupation certificate is issued for all parts of the building or buildings to which the\ndevelopment consent relates.","stage":"general","stage_basis":"heading","page":3},{"label":"A060","code":"A060","number":null,"title":"Erection of signs","text":"3 Building Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nThis section applies to a development consent for development involving building work, subdivision work or demolition work.\nIt is a condition of the development consent that a sign must be erected in a prominent position on a site on which building work, subdivision work or demolition work is\nbeing carried out-\nshowing the name, address and telephone number of the principal certifier for the work, and\nshowing the name of the principal contractor, if any, for the building work and a telephone number on which the principal contractor may be contacted outside\nworking hours, and\nstating that unauthorised entry to the work site is prohibited.\nThe sign must be-\nmaintained while the building work, subdivision work or demolition work is being carried out, and\nremoved when the work has been completed.\nThis section does not apply in relation to-\nbuilding work, subdivision work or demolition work carried out inside an existing building, if the work does not affect the external walls of the building, or\nCrown building work certified to comply with the Building Code of Australia under the Act, Part 6.","stage":"general","stage_basis":"heading","page":3},{"label":"A950","code":"A950","number":null,"title":"Sydney Water Requirements","text":"The development shall comply in full with all requirements outlined within the correspondence prepared by Sydney Water dated 29/08/2023 and\nall conditions contained therein.","stage":"general","stage_basis":"heading","page":4},{"label":"B008","code":"B008","number":null,"title":"Housing and Productivity Contribution","text":"Before the issue of a relevant construction certificate, the applicant is to make a Housing and Productivity Contribution payment through the NSW Planning Portal.","stage":"before_cc","stage_basis":"heading","page":4},{"label":"B010","code":"B010","number":null,"title":"Design amendments","text":"Before the issue of a construction certificate, amended plans are to be provided to Council for approval by the Senior Development Assessment\nPlanner for approval. The certifier must ensure the construction certificate plans and specifications detail the following required amendments to the approved plans and\ndocuments:\nAmended Architectural plans are to be provided that include the following: i) Fixed site screens are to be provided to the windows and balconies units on the northwestern\nside of the development that have the potential to overlook the outdoor play area of the Childcare Centre approved under DA42/2024 on the adjoining two sites to the west\nof the subject site ii) 1.5 cubic metres of additional storage is to be provided (possibly in the basement) for Unit L5U2 iii) ceiling fans are to be incorporated in\nbedrooms and living areas of the units iv) openable windows are to be provided to perimeter bathrooms to improve natural ventilation v) EV charging points are to be\nprovided in the basement area vii) rainwater harvesting infrastructure (including water taps to maintain all landscaping areas) is to be provided to permit stormwater reuse\non the site, vii) the location and orientation of the fire hydrant booster shall be revised to minimize their impact on the streetscape. The location of the hydrant booster\nshall not impede on pedestrian access paths or the required visual site lines of vehicles utilizing the basement driveway.\nAmended landscape plans are to be provided that include i) the removal of planting on the balconies of individual units ii) provides further details on how vine growth over\nthe driveway entrance is facilitated and nominate appropriate species as part of the landscape drawings.","stage":"before_cc","stage_basis":"heading","page":4},{"label":"B020","code":"B020","number":null,"title":"Equal access to the premises","text":"Before the issue of a construction certificate, plans which demonstrate that adequate access to the premises will be provided for persons with disabilities in accordance with the\nCommonwealth Disability (Access to Premises - Buildings) Standards 2010. These plans must be submitted to the certifier.","stage":"before_cc","stage_basis":"heading","page":4},{"label":"B038","code":"B038","number":null,"title":"Utilities and services","text":"Before the issue of a Construction Certificate, written evidence of the following service provider requirements must be provided to the certifier.\na letter from Endeavour Energy demonstrating that satisfactory arrangements can be made for the installation and supply of electricity;\na response from Sydney Water as to whether the approved development would affect any Sydney Water infrastructure, and whether further requirements need to be met;\nother relevant utilities or services that the development as proposed to be carried out is satisfactory to those other service providers, or if it is not, the changes that are\nrequired to make the development satisfactory to them.","stage":"before_cc","stage_basis":"heading","page":4},{"label":"B048","code":"B048","number":null,"title":"A Provision of Services Street Lighting","text":"The applicant/developer shall engage the services of an Endeavour Energy accredited ASP Level 3 service provider who shall request Council’s Transport Management Team’s\nendorsement of a Public Street Lighting Design Brief.\nThe consultant is to lodge Endorsement of Public Lighting Design Application Form. The application is available on Council website and should be lodged online.\nOnce endorsed, the Designer is to carry out assessment of the existing street lighting and carry out a street lighting improvement design. This is to be submitted to and\napproved by Endeavour Energy.\nThe upgrade may include undergrounding of existing aerial power lines, communication cables and replacement of existing street light poles with Endeavour Energy approved\nMacarthur Poles as specified by Council in the public lighting design brief.","stage":"before_cc","stage_basis":"heading","page":4},{"label":"B054","code":"B054","number":null,"title":"Retaining Walls on Boundary","text":"All retaining walls shall be of masonry construction and must be wholly within the property boundary, including footings and agricultural drainage\nlines. Construction of retaining walls or associated drainage works along common boundaries shall not compromise the structural integrity of any existing structures.\nWhere a retaining wall exceeds 600mm in height, the wall shall be designed by a practicing structural engineer and a construction certificate must be obtained prior to\ncommencement of works on the retaining wall.","stage":"before_cc","stage_basis":"heading","page":4},{"label":"B055","code":"B055","number":null,"title":"S138 Roads Act roadworks requiring approval of civil drawings","text":"Prior to the issue of a Construction Certificate for building or subdivision works the Certifying Authority shall ensure that a S138 Roads Act\napplication, including the payment of application and inspection fees, has been lodged with Liverpool City Council (being the Roads Authority under the Roads Act), for provision\nof Stormwater Drainage, kerb inlet pit and lintel and 1.5m wide concrete footpath to full site frontage in Mckay avenue.\nEngineering plans are to be prepared in accordance with the development consent, Liverpool City Council’s Design Guidelines and Construction Specification for Civil Works,\nAustroad Guidelines and best engineering practice.\nNote: Where Liverpool City Council is the Certifying Authority for the development the Roads Act approval for the above works may be issued concurrently with the Construction\nCertificate.","stage":"before_cc","stage_basis":"heading","page":4},{"label":"B075","code":"B075","number":null,"title":"Fee Payments","text":"Unless otherwise prescribed by this consent, all relevant fees or charges must be paid. Where Council does not collect these payments, copies of receipts must be provided.\nThe following fees are applicable and payable:\nDamage Inspection Fee - relevant where the cost of building work is $20,000 or more, or a swimming pool is to be excavated by machinery.\nFee associated with Application for Permit to Carry Out Work Within a Road, Park and Drainage Reserve.\n(a)\n(b)\n4 Building Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nThese fees are reviewed annually and will be calculated accordingly.","stage":"before_cc","stage_basis":"heading","page":4},{"label":"B081","code":"B081","number":null,"title":"Site Development Work","text":"Site development work in the form of excavation, underpinning or shoring works must not take place, until such time as a CC has been issued.","stage":"before_cc","stage_basis":"heading","page":5},{"label":"B095","code":"B095","number":null,"title":"Long Service Levy","text":"Before the issue of a Construction Certificate, Long Service Levy payment is applicable on building work having a value of $250,000 or more, at\nthe rate of 0.25% of the cost of the works. The required Long Service Levy payment, under the Building and Construction Industry Long Service Payments Act 1986, is to be\nforwarded to the Long Service Levy Corporation or the Council, prior to the issuing of a Construction Certificate, in accordance with Section 6.8 of the Environmental Planning &\nAssessment Act 1979.","stage":"before_cc","stage_basis":"heading","page":5},{"label":"B099","code":"B099","number":null,"title":"Substation","text":"Should the Electrical Substation be located outside the building envelope, the location and any associated fire separation walls must comply with Integral Energy Substation\nDesign Instruction Document No SDI 104 (Current Version).","stage":"before_cc","stage_basis":"heading","page":5},{"label":"B112","code":"B112","number":null,"title":"Notification","text":"In the event that Council is not the Principal Certifier (PC), the PC must advise Council, in writing of:\nIf these arrangements are changed, or if a contact is entered into for the work to be done by a different licensee, Council must be immediately informed.","stage":"before_cc","stage_basis":"heading","page":5},{"label":"B116","code":"B116","number":null,"title":"Products banned under the Building Products (Safety) Act 2017","text":"No building products that are banned, or products that are subject to a ban if used in a particular way under the Building Products (Safety) Act 2017 are to be used in the\nconstruction of the development.","stage":"before_cc","stage_basis":"heading","page":5},{"label":"B120","code":"B120","number":null,"title":"Cladding","text":"Prior to issue of a construction certificate the certifier must be satisfied that all proposed attachments, cladding material and systems forming part of external walls comply with\nthe BCA and relevant Australian Standards. The certifier must be able to demonstrate compliance with evidence of suitability as per clause A2G2 of BCA Volume 1 for all\nproducts/systems proposed.","stage":"before_cc","stage_basis":"heading","page":5},{"label":"B129","code":"B129","number":null,"title":"Design Verification Statement","text":"In accordance with the EP&A Regulation and State Environmental Planning Policy (SEPP) 65 “Design Quality of Residential Flat Development”, the subject development must\nbe undertaken or directed by a ‘qualified designer’ (i.e., a registered architect under the Architects Act). In this regard, a design verification statement shall be submitted to the\nPrivate Certifier (PC). The PC shall ensure that the statement prepared by the qualified designer provides the following:\nNote: The design verification statement must provide an explanation of the design in terms of the design quality principles set out in Part 2 of SEPP 65.","stage":"before_cc","stage_basis":"heading","page":5},{"label":"B134","code":"B134","number":null,"title":"Crime Prevention Through Environmental Design","text":"The following Crime Prevention through Environmental Design (CPTED) principles are to be incorporated into the building:\nWhere necessary, plans shall be amended to reflect incorporation of the principles and/or details of such to be submitted to the Private Certifier.","stage":"before_cc","stage_basis":"heading","page":5},{"label":"B135","code":"B135","number":null,"title":"Provision of Services Sydney Water","text":"Prior to the issue of a Construction Certificate, an application to obtain a Section 73 Compliance Certificate under the Sydney Water Act 1994, is to be lodged with Sydney\nWater. To facilitate this, an application must be made through an authorised Water Servicing Coordinator. Please refer to the “building and developing” section of Sydney\nWater’s web site at www.sydneywater.com.au, or telephone 13 20 92.\nFollowing receipt of the application, a ‘Notice of Requirements’ will detail water and sewer extensions to be built and charges to be paid. Please make early contact with the\nCoordinator, since building of water/sewer extensions can be time consuming and may impact on other services and building, driveway or landscape design. A copy of the\n‘Notice of Requirements’ must be submitted to the PCA, prior to the issue of a Subdivision Works Certificate.","stage":"before_cc","stage_basis":"heading","page":5},{"label":"B136","code":"B136","number":null,"title":"Provision of Services Endeavour Energy","text":"Prior to the issue of a Construction Certificate, a written clearance from Endeavour Energy, stating that electrical services have been made available to the development or that\narrangements have been entered into for the provision of services to the development must be submitted to the Principal Certifier.","stage":"before_cc","stage_basis":"heading","page":5},{"label":"B137","code":"B137","number":null,"title":"Provision of Services Telecommunications","text":"Prior to the issue of a Construction Certificate, the Principal Certifier shall be satisfied that telecommunications infrastructure may be installed to service the premises which\ncomplies with the following requirements of the Telecommunications Act 1997:\nFor a fibre ready facility, the NBN Co’s standard specifications current at the time of installation, and\nFor a line that is to connect a lot to telecommunications infrastructure external to the premises, the line shall be located underground.\nUnless otherwise stipulated by telecommunications legislation at the time of construction, the development must be provided with all necessary pits and pipes, and conduits to\naccommodate the future connection of optic fibre technology telecommunications.\nThe name and contractor licence number of the licensee who has contracted to do or intends to do the work, or\nThe name and permit of the ownerbuilder who intends to do the work.\na valid and current chartered architect’s certificate number (as issued by the Board of Architects of NSW),\nthat the qualified designer has designed or directed the design of the subject development, and\nthat the plans and specifications lodged with the CC achieve or improve the design quality of the development for which the subject development consent was granted,\nhaving regard to the design principles set out in Part 2 of SEPP 65.\nback to base alarm system (only if commercial near residential),\nbasement parking areas shall be painted a light colour,\nCCTV for the ground level, entry/exit points, car parks, lifts and the exterior of the building,\n‘way finding’ signage should be utilised at all major interchanges such as lifts and stair wells,\nlighting is required to be designed in accordance with the Australian and New Zealand Lighting Standard AS 1158. A lighting maintenance policy should be established.\nSecurity lighting should be installed in and around the building, and such shall not impact on any adjoining premises. The lighting should be vandal resistant, especially\nexternal lighting,\ncorrugated ramps to prevent skate boarding activities,\nglazed tiling, patterned, porous and non solid surfaces reduce the reward for graffiti offenders,\nany external approved palisade or pool style fencing shall be black in colour, unless otherwise noted on the approved plans/details, and\naccess to the basement parking levels relating to the residential component of the building shall be controlled via a security controlled device.\n(a)\n(b)\n(a)\n(b)\n(c)\n(a)\n(b)\n(c)\n(d)\n(e)\n(f)\n(g)\n(h)\n(i)\n5 Building Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work","stage":"before_cc","stage_basis":"heading","page":5},{"label":"B149","code":"B149","number":null,"title":"S138 Roads Act Minor Works in the public road","text":"Prior to the issue of a Construction Certificate, a Section 138 Roads Act application/s, including payment of fees, shall be lodged with Liverpool City Council, as the Roads\nAuthority for any works required in a public road. These works may include but are not limited to:\nAll works shall be carried out in accordance with the Roads Act approval, the development consent including the stamped approved plans, and Liverpool City Council’s\nspecifications.\nNote: Approvals may also be required from the Transport for NSW for classified roads.","stage":"before_cc","stage_basis":"heading","page":6},{"label":"B156","code":"B156","number":null,"title":"Waste Storage Room","text":"Prior to the issuing of a construction certificate, the principal certifier shall be satisfied that the designated garbage/waste storage area shall comply with the following\nrequirements:\nThe room shall be fully enclosed and provided with a concrete floor, and with concrete or cement rendered walls coved to the floor;\nThe room shall have a floor waste which is to consist of a removable basket within a fixed basket arrestor and is to comply with Sydney Water requirements; and\nThe door to the room must be tightfitting, selfclosing and fitted with mechanical ventilation.\nPlease refer to the Liverpool Development Control Plan 2008 for further information regarding the construction standards for waste storage areas.","stage":"before_cc","stage_basis":"heading","page":6},{"label":"B158","code":"B158","number":null,"title":"Construction Traffic Management Plan (CTMP)","text":"A construction traffic management plan (CTMP) prepared by a suitably qualified person is to be submitted to and endorsed by Council’s Transport Management Section. The\nCTMP is to be submitted using Assessment of Construction Traffic Management Plan application form. The application is available on Council website and can be lodged online.\nComments on the CTMP will be provided and the updated CTMP are to be implemented during construction.\nA copy of the endorsed CTMP and traffic control plans are to be available on the works site for inspection by authorised Council officers.\nConstruction shall not commence until the assessed construction traffic management plan has been endorsed. The endorsed CTMP is to be implemented during construction.","stage":"before_cc","stage_basis":"heading","page":6},{"label":"B360","code":"B360","number":null,"title":"Construction Environmental Management Plan (CEMP)","text":"Prior to issue of a construction certificate, a Construction Environmental Management Plan (CEMP) for the development must be provided to the\nPrincipal Certifying Authority for approval. The environmental site management measures must remain in place and be maintained throughout the period of the development. The\nCEMP must address all environmental aspects of the development’s construction phases, and include (where relevant), but not be limited to, the following:\nAsbestos Management Plan;\nProject Contact Information;\nSite Security Details;\nTiming and Sequencing Information;\nSite Soil and Water Management Plan;\nNoise and Vibration Control Plan; This plan is to incorporate alternate methods of construction that minimise noise and vibration impacts (during the excavation and\nconstruction stages) to adjoining uses including the adjacent childcare centre currently under construction to the west of the site. Methods that avoid pile driving in the\nbasement are required. Consideration of the timing of construction activities is also to be included.\nDust Control Plan;\nAir Monitoring;\nOdour Control Plan;\nHealth and Safety Plan;\nWaste Management Plan;\nIncident management Contingency; and\nUnexpected Finds Protocol.\nThe CEMP must be kept on site for the duration of the works and must be made available to Council Officers upon request","stage":"before_cc","stage_basis":"heading","page":6},{"label":"B361","code":"B361","number":null,"title":"Construction Site Management Plan","text":"Before the issue of a Construction Certificate, a construction site management plan must be prepared, and provided to the certifier. The plan\nmust include the following matters:\nThe location and materials for protective fencing and hoardings on the perimeter of the site;\nProvisions for public safety;\nPedestrian and vehicular site access points and construction activity zones;\nDetails of construction traffic management including:\nProposed truck movements to and from the site;\nEstimated frequency of truck movements; and\nMeasures to ensure pedestrian safety near the site;\nDetails of bulk earthworks to be carried out;\nThe location of site storage areas and sheds;\nThe equipment used to carry out works;\nThe location of a garbage container with a tightfitting lid;\nDust, noise and vibration control measures;\nThe location of temporary toilets;\nThe protective measures for the preservation of trees onsite and in adjoining public areas including measures in accordance with:\nAS 4970 - Protection of trees on development sites;\nAn applicable Development Control Plan;\nAn arborist’s report approved as part of this consent\nA copy of the construction site management plan must be kept onsite at all times while work is being carried out.","stage":"before_cc","stage_basis":"heading","page":6},{"label":"B380","code":"B380","number":null,"title":"Mechanical Plant and Equipment","text":"Before the issue of a construction certificate, the certifier must be satisfied that mechanical plant and equipment were selected in consultation with a suitably qualified acoustic\nconsultant in accordance with the recommendations of the approved acoustic report.\nNote: The ‘suitably qualified acoustic consultant’ must be a member of the Australian Acoustical Society or employed by an Association of Australasian Acoustical Consultants\n(AAAC) member firm.","stage":"before_cc","stage_basis":"heading","page":6},{"label":"B407","code":"B407","number":null,"title":"Car parking details","text":"Before the issue of a Construction Certificate, written evidence prepared by a suitably qualified engineer must be obtained that demonstrates, to the certifier’s satisfaction, the\nplans for parking facilities comply with the relevant parts of AS 2890.1 Parking Facilities OffStreet Carparking and <Insert part(s), section(s) or clause(s)> of Council’s\nrelevant development control plan (in force as at the date of determination of this consent).","stage":"before_cc","stage_basis":"heading","page":6},{"label":"B408","code":"B408","number":null,"title":"Access, Car Parking and Manoeuvring General","text":"Vehicular crossings (including kerb reinstatement of redundant vehicular crossings),\nRoad opening for utilities and stormwater (including stormwater connection to Council infrastructure), or\nRoad occupancy or road closures.\n(a)\n(b)\n(c)\n6 Building Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nThe Certifying Authority shall ensure and certify that vehicular access, circulation, manoeuvring, pedestrian and parking areas associated with the subject development have\nbeen designed and are in accordance with AS 2890.1, AS2890.2, AS2890.6 and Council’s Development Control Plan.","stage":"before_cc","stage_basis":"heading","page":6},{"label":"B410","code":"B410","number":null,"title":"Access, Car Parking and Manoeuvring Detail","text":"The Certifying Authority shall ensure and certify that:\nOff street access and parking complies with AS2890.1,\nVehicular access and internal manoeuvring have been designed for the longest (BDouble/ Heavy Rigid/ Medium Rigid) vehicle expected to service the development site,\nin accordance with AS2890.2,\nSight distance at the street frontage has been provided in accordance with AS 2890.1,\nAll vehicles can enter and exit the site in a forward direction, and/or\nRequirements of the Disability Discrimination Act 2002, Disability Standards for Accessible Public Transport and the Guidelines for assessing compliance of bus stops\nwith the Disability Standards for Accessible Public Transport 2002, DA No. (insert) Page xx of xxx.","stage":"before_cc","stage_basis":"heading","page":7},{"label":"B452","code":"B452","number":null,"title":"Stormwater Discharge Basement Car parks","text":"Prior to the issue of a Construction Certificate the Certifying Authority shall ensure that the stormwater drainage system for the basement car park has been designed in\naccordance with the requirements for pumped systems in AS3500.3:2003 and Council’s Stormwater Drainage Design Specifications for pump out systems for basement\ncarparks.","stage":"before_cc","stage_basis":"heading","page":7},{"label":"B456","code":"B456","number":null,"title":"OnSite Detention","text":"OnSite Detention shall be provided generally in accordance with the concept plan/s lodged for development approval, prepared by Loka\nConsulting Engineers, reference number 22NL062, revision C, dated 19/08/2024\nThe proposed development and stormwater drainage system shall be designed to ensure that stormwater runoff from upstream properties is conveyed through the site without\nadverse impact on the development or adjoining properties.\nEngineering plans and supporting calculations for the onsite detention system are to be prepared by a suitably qualified person and shall accompany the application for a\nConstruction Certificate.\nPrior to the issue of a Construction Certificate the Certifying Authority shall ensure that the onsite detention system has been designed in accordance with Liverpool City\nCouncil’s Design Guidelines and Liverpool City Council’s OnSite Stormwater Detention policy and Technical Specification.","stage":"before_cc","stage_basis":"heading","page":7},{"label":"B462","code":"B462","number":null,"title":"Water Quality","text":"Prior to the issue of a Construction Certificate, the Certifying Authority shall ensure that details of a stormwater pretreatment system have been provided on the stormwater\nplans and that the design meets pollutant retention criteria in accordance Council’s Development Control Plan.\nThe Construction Certificate must be supported by:\nA copy of the approved operation and maintenance manual/ schedule shall be submitted to Liverpool City Council with notification of the Construction Certificate issue.","stage":"before_cc","stage_basis":"heading","page":7},{"label":"B555","code":"B555","number":null,"title":"Detailed Design Drawings","text":"The applicant is to discuss with Council’s Traffic Management Section of the traffic requirements prior to undertaking the detailed design of traffic\nfacilities, signs and linemarking in the existing and/or proposed public domain.\nThe plans should include, but not be limited to:\n600mm wide central median on McKay Avenue along the site frontage extended by about 10m past the driveway on the western side to effectively enforce the left in left\nout arrangement,\nSwept path diagrams are to be provided to demonstrate that vehicles can manoeuvre in and out of the driveway,\n“keep left” sign at both ends of the central median. Note: the narrow vertical sign as proposed by the traffic consultant has been superseded.\nDetailed design drawings of the proposed traffic facilities, signs and line markings in the existing and proposed public domain areas are to be submitted to Council for approval\nusing Approval of Traffic Facilities including Signs and Line Marking Schemes Application Form. The application is available on Council website and should be lodged online.\nThe drawings are to be prepared by a suitably qualified person.","stage":"before_cc","stage_basis":"heading","page":7},{"label":"B560","code":"B560","number":null,"title":"Road Works","text":"Works within the public road reserve shall not commence until the design drawings including the associated signs and line marking scheme have been approved by Council’s\nTraffic Management Section.","stage":"before_cc","stage_basis":"heading","page":7},{"label":"B590","code":"B590","number":null,"title":"Public Domain Works - Street Lighting","text":"The approved street lighting designs are to be implemented along all new and existing streets within the proposed development in accordance with Liverpool City Council\nstandards and to the satisfaction of Council.\nAll street lighting must comply with the service provider Street Lighting Policy and illumination requirements and Council’s Street Lighting policy.\nAll cost associated with the installation of street lighting shall be borne by the developer.","stage":"before_cc","stage_basis":"heading","page":7},{"label":"B952","code":"B952","number":null,"title":"NonStandard Condition Land Development Engineering","text":"Titles and Contents of NonStandard Conditions","stage":"before_cc","stage_basis":"heading","page":7},{"label":"B953","code":"B953","number":null,"title":"NonStandard Condition Land Development Engineering","text":"Titles and Contents of NonStandard Conditions","stage":"before_cc","stage_basis":"heading","page":8},{"label":"C005","code":"C005","number":null,"title":"Construction Certificates","text":"Prior to the commencement of any building works, the following requirements must be complied with:","stage":"before_work","stage_basis":"heading","page":8},{"label":"C010","code":"C010","number":null,"title":"Construction Certificates","text":"Any Construction Certificate that may be issued in association with this development consent must ensure that any certified plans and designs are generally consistent (in\nterms of site layout, site levels, building location, size, external configuration and appearance) with the approved Development Application plans.","stage":"before_work","stage_basis":"heading","page":8},{"label":"C012","code":"C012","number":null,"title":"Commencement of building works","text":"Building work shall not commence prior to the issue of a Construction Certificate. Building work as defined under Section 1.4 of the Environmental Planning and Assessment\nAct, 1979 means any physical activity involved in the erection of a building and includes but is not limited to, the placement of any site shed/s or builders facilities, site grading,\nretaining walls, excavation, cutting trenches, installing formwork and steel reinforcement or, placing of plumbing lines.","stage":"before_work","stage_basis":"heading","page":8},{"label":"C039","code":"C039","number":null,"title":"Construction Requirements","text":"Retaining walls or other approved methods necessary to prevent the movement of excavated or filled ground, together with associated subsoil drainage and surface stormwater\ndrainage measures, shall be designed strictly in accordance with the manufacturers details or by a practising structural engineer. Retaining walls on any boundary are to be of\nmasonry construction or if treated timber is used, all vertical support members (soldiers) shall be of galvanised steel.","stage":"before_work","stage_basis":"heading","page":8},{"label":"C040","code":"C040","number":null,"title":"Demolition Works","text":"Demolition works shall be carried out in accordance with the following:\nConstruction Certificate must be obtained from the Council or an Accredited Certifier, in accordance with the provisions of the Environmental Planning & Assessment Act\n1979,\nWhere a Construction Certificate is obtained from an Accredited Certifier, the applicant shall advise Council of the name, address and contact number of the Accredited\nCertifier, in accordance with Section 4.19, 6.6, 6.7, 6.12, 6.13, 6.14 of the Act,\nA copy of the Construction Certificate, the approved development consent plans and consent conditions must be kept on the site at all times and be made available to\nthe Council officers and all building contractors for assessment,\nA Principal Certifier (PC) must be appointed to carry out the necessary building inspections and to issue an occupation certificate, and\nThe PC must advise Council of the intended date to commence work which is the subject of this consent by completing a notice of commencement of building works or\nsubdivision works form, available from Council’s Customer Service Centre. A minimum period of two (2) working days’ notice must be given.\n(a)\n(b)\n(c)\n(d)\n(e)\n8 Demolition Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work","stage":"before_work","stage_basis":"heading","page":8},{"label":"C042","code":"C042","number":null,"title":"Disconnection of services before demolition work","text":"Before demolition work commences, all services, such as water, telecommunications, gas, electricity and sewerage, must be disconnected in accordance with the relevant\nauthority’s requirements.","stage":"before_work","stage_basis":"heading","page":9},{"label":"C055","code":"C055","number":null,"title":"Site Facilities","text":"Adequate refuse disposal methods and builders storage facilities shall be installed on the site. Builders’ wastes, materials or sheds are not to be placed on any property other\nthen that which this approval relates to.","stage":"before_work","stage_basis":"heading","page":9},{"label":"C065","code":"C065","number":null,"title":"Sydney Water","text":"Development plans must be processed and approved by Sydney Water.","stage":"before_work","stage_basis":"heading","page":9},{"label":"C070","code":"C070","number":null,"title":"\"DIAL BEFORE YOU DIG\"","text":"Underground assets may exist in the area that is subject to your application. In the interest of health and safety and in order toprotect damage to third party assets please\ncontact Dial before you dig at www.1100.com.au or telephone 1100 before excavating or erecting structures (This is the law in NSW). If alterations are required to the\nconfiguration, size, form or design of the development upon contact the Dial before You Dig service, an amendment to the development consent (or a new development\napplication) may be necessary. Individuals owe asset owners a duty of care that must be observed when working in the vicinity of plant or assets. It is the individual’s\nresponsibility to anticipate and request the nominal location of plant or assets on the relevant property via contacting the Dial before you dig service in advance of any\nconstruction or planning activities.","stage":"before_work","stage_basis":"heading","page":9},{"label":"C117","code":"C117","number":null,"title":"Erosion and sediment controls in place","text":"Before any site work commences, the principal certifier or Council, must be satisfied the erosion and sediment controls in the erosion and\nsediment control plan are in place. These controls must remain in place until any bare earth has been restabilised in accordance with 'Managing Urban Stormwater: Soils and\nConstruction’ prepared by Landcom (the Blue Book) (as amended from time to time).","stage":"before_work","stage_basis":"heading","page":9},{"label":"C126","code":"C126","number":null,"title":"Environmental Management","text":"Adequate soil and sediment control measures shall be installed and maintained. Furthermore, suitable site practices shall be adopted to ensure that only clean and unpolluted\nwaters are permitted to enter Council’s stormwater drainage system during construction/demolition. Measures must include, as a minimum:\nSiltation fencing;\nProtection of the public stormwater system; and\nSite entry construction to prevent vehicles that enter and leave the site from tracking loose material onto the adjoining public place.","stage":"before_work","stage_basis":"heading","page":9},{"label":"C155","code":"C155","number":null,"title":"Work Zone","text":"A Works Zone application is required if onstreet parking is affected with commuter parking and there is insufficient offstreet parking space.\nA Works Zone Application Form is available on Council website and can be lodged online by attaching all required documents indicated on the application form.","stage":"before_work","stage_basis":"heading","page":9},{"label":"C158","code":"C158","number":null,"title":"Construction Traffic Management Plan (CTMP)","text":"A construction traffic management plan (CTMP) prepared by a suitably qualified person is to be submitted to and endorsed by Council’s Transport Management Section. The\nCTMP is to be submitted using Assessment of Construction Traffic Management Plan application form. The application is available on Council website and can be lodged online.\nComments on the CTMP will be provided and the updated CTMP are to be implemented during construction.\nA copy of the endorsed CTMP and traffic control plans are to be available on the works site for inspection by authorised Council officers.\nConstruction shall not commence until the assessed construction traffic management plan has been endorsed. The endorsed CTMP is to be implemented during construction.","stage":"before_work","stage_basis":"heading","page":9},{"label":"C201","code":"C201","number":null,"title":"Road Occupancy Permit","text":"Road occupancy and road opening approvals will be required from Council to undertake works within the existing road reserve. The following applications are available on\nCouncil’s website and can be lodged online attaching all required documents indicated on the application form.\nRoad Occupancy Application Form\nRoad Opening Application Form","stage":"before_work","stage_basis":"heading","page":9},{"label":"C205","code":"C205","number":null,"title":"Traffic Control Plan","text":"Prior to commencement of works a Traffic Control Plan including details for pedestrian management, shall be prepared in accordance with AS1742.3 “Traffic Control Devices for\nWorks on Roads” and the Roads and Traffic Authority’s publication “Traffic Control at Worksites” and certified by an appropriately accredited Roads and Traffic Authority Traffic\nController.\nTraffic control measures shall be implemented during the construction phase of the development in accordance with the certified plan. A copy of the plan shall be available on\nsite at all times.\nNote: A copy of the Traffic Control Plan shall accompany the Notice of Commencement to Liverpool City Council.","stage":"before_work","stage_basis":"heading","page":9},{"label":"C250","code":"C250","number":null,"title":"Notification","text":"Notification to surrounding residents is to be undertaken within a 100 metre radius from the site. A letter box drop in the form of an informative pamphlet or the like is to be\ncarried out at least 5 days prior to the event to local residents informing them of the event details and including contact details of the site supervisor for the event.","stage":"before_work","stage_basis":"heading","page":9},{"label":"C466","code":"C466","number":null,"title":"Dilapidation report","text":"A full dilapidation survey and report on the visible and structural condition, with comment on the footings and foundations, of all neighbouring\nstructures within the ‘zone of influence’ of the required excavations must be submitted to the Principal Certifier for approval prior to the issue of any Construction Certificate. The\nzone of influence is to be defined as the horizontal distance from the edge of the excavation face to twice the excavation depth.\nThe dilapidation report, survey and comments are to be prepared by a consulting structural/geotechnical engineer agreed to by both the applicant and the owner of any affected\nadjoining property. A copy is also to be provided to the affected adjoining property owner/s.\nAll costs incurred in achieving compliance with this condition shall be borne by the person entitled to act on this Consent.\nPrior to the commencement of any works on the land, a detailed demolition work plan designed in accordance with the Australian Standard AS 26012001 - The\nDemolition of Structures, prepared by a suitably qualified person with suitable expertise or experience, shall be submitted to and approved by Council and shall include\nthe identification of any hazardous materials, method of demolition, precautions to be employed to minimise any dust nuisance and the disposal methods for hazardous\nmaterials.\nPrior to commencement of any works on the land, the demolition Contractor(s) licence details must be provided to Council.\nThe handling or removal of any asbestos product from the building/site must be carried out by a SafeWork NSW licensed contractor irrespective of the size or nature of\nthe works. Under no circumstances shall any asbestos on site be handled or removed by a nonlicensed person. The licensed contractor shall carry out all works in\naccordance with SafeWork NSW requirements.\n(a)\n(b)\n(c)\n9 Demolition Work\nDemolition Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nIf access for undertaking the dilapidation survey is denied by an adjoining owner, the applicant must:\na)Undertake as much as possible the survey from the development site, public areas and/or adjoining private property, and\nb)Demonstrate in writing to the satisfaction of the Principal Certifier that all reasonable steps have been taken to obtain access and advise the affected property owner of the\nreason for the survey and that these steps have failed.\nNote: This documentation is for record keeping purposes only and may be used by the developer or affected property owner to assist in any action required to resolve any\ndispute over damage to adjoining properties arising from the works. It is in the applicant’s and adjoining owner’s interest for it to be as full and detailed as possible.","stage":"before_work","stage_basis":"heading","page":9},{"label":"C501","code":"C501","number":null,"title":"Return of existing bins","text":"Prior to commencing demolition or site clearing works, any existing domestic waste bins that have been issued to (insert address), must be returned to Liverpool City Council.\nPlease ring Council on 1300 36 2170 to advise that the bins are empty and ready to be removed, so their removal can be noted on Council’s rates system.","stage":"before_work","stage_basis":"heading","page":10},{"label":"C502","code":"C502","number":null,"title":"Remove and destroy refrigerants","text":"Prior to any works commencing, any airconditioning or refrigeration systems fitted to the buildings or outbuildings to be demolished, must have the refrigerants present in those\nsystems extracted into a durable, airtight container by a licensed airconditioning technician. This container and its contents must be sent intact, for secure destruction, to a\nfacility licensed to destroy such refrigerants. Documentary evidence that this has been completed, if these systems are present, must be sighted by the Principal Certifying\nAuthority and included as part of the Occupation Certificate documentation.","stage":"before_work","stage_basis":"heading","page":10},{"label":"C950","code":"C950","number":null,"title":"Fire Safety Measures","text":"A schedule specifying all of the essential fire safety services, which are required for the building, shall be attached to the CC and submitted to\nCouncil, in compliance with the provisions of the EP&A Regulation.","stage":"before_work","stage_basis":"heading","page":10},{"label":"D005","code":"D005","number":null,"title":"Building Work","text":"The building works must be inspected by the Principal Certifier (PC), in accordance with Sections 6.5 of the Environmental Planning & Assessment Act 1979, to monitor\ncompliance with the relevant standards of construction, Council’s development consent and the construction certificate.","stage":"during_work","stage_basis":"heading","page":10},{"label":"D010","code":"D010","number":null,"title":"Building Work","text":"The Principal Certifier (PC) must specify the relevant stages of construction to be inspected and a satisfactory inspection must be carried out, to the satisfaction of the PC, prior\nto proceeding to the subsequent stages of construction or finalisation of the works.","stage":"during_work","stage_basis":"heading","page":10},{"label":"D015","code":"D015","number":null,"title":"Surveys by a registered surveyor","text":"While building work is being carried out, the positions of the following must be measured and marked by a registered surveyor and provided to the principal certifier:\nAll footings / foundations in relation to the site boundaries and any registered and proposed easements\nAt other stages of construction - any marks that are required by the principal certifier.","stage":"during_work","stage_basis":"heading","page":10},{"label":"D020","code":"D020","number":null,"title":"Identification Survey Report","text":"The building and external walls are not to proceed past ground floor/reinforcing steel level until such time as the Principal Certifier has been supplied with an identification survey\nreport prepared by a registered surveyor certifying that the floor levels and external wall locations to be constructed, comply with the approved plans, finished floor levels and\nsetbacks to boundary/boundaries. The slab shall not be poured, nor works continue, until the Principal Certifier has advised the builder/developer that the floor level and external\nwall setback details shown on the submitted survey are satisfactory.\nIn the event that Council is not the Principal Certifier, a copy of the survey shall be provided to Council within three (3) working days.","stage":"during_work","stage_basis":"heading","page":10},{"label":"D025","code":"D025","number":null,"title":"Identification Survey Report","text":"On placement of the concrete, works again shall not continue until the Principal Certifier has issued a letter stating that the condition of the approval has been complied with and\nthat the slab has been poured at the approved levels.","stage":"during_work","stage_basis":"heading","page":10},{"label":"D028","code":"D028","number":null,"title":"Responsibility for changes to public infrastructure","text":"While site work is being carried out, any costs incurred as a result of the approved removal, relocation or reconstruction of infrastructure (including ramps, footpaths, kerb and\ngutter, light poles, kerb inlet pits, service provider pits, street trees or any other infrastructure in the street footpath area) must be paid as directed by the consent authority.","stage":"during_work","stage_basis":"heading","page":10},{"label":"D030","code":"D030","number":null,"title":"Security and Safety","text":"Adequate lighting is required to be provided at the entrance and main foyer of the building, basement carpark, and mailbox area.\nSurveillance cameras are required to be installed covering the entrance and exit and main areas of the car park.\nAll openable windows that are located two metres or more above the ground level and have a sill height less than 1.7m above the internal floor level shall be fitted with devices\nthat lock the window opening at less than 12.5m.","stage":"during_work","stage_basis":"heading","page":10},{"label":"D038","code":"D038","number":null,"title":"Toilet Facilities","text":"Toilet facilities must be available or provided at the work site and must be maintained until the works are completed at a ratio of one toilet plus one additional toilet for every 20\npersons employed at the site. Each toilet must:","stage":"during_work","stage_basis":"heading","page":10},{"label":"D042","code":"D042","number":null,"title":"Procedure for critical stage inspections","text":"While building work is being carried out, the work must not continue after each critical stage inspection unless the principal certifier is satisfied the work may proceed in\naccordance with this consent and the relevant construction certificate.","stage":"during_work","stage_basis":"heading","page":10},{"label":"D045","code":"D045","number":null,"title":"Hours of work","text":"Site work must only be carried out between the following times -\nFor work/civil work/demolition work, including delivery of materials is only permitted on the site from 7:00am to 6:00pm on Monday to Friday.\nFor work/civil work/demolition work, including delivery of materials is only permitted on the site from 8:00am to 1:00pm on Saturday.\nSite work is not to be carried out outside of these times except where there is an emergency, or for urgent work directed by a police officer or a public authority.\nbe a standard flushing toilet connected to a public sewer, or\nhave an onsite effluent disposal system approved under the Local Government Act 1993, or\nbe a temporary chemical closet approved under the Local Government Act 1993.\n(a)\n(b)\n(c)\n10 Building Work\nDemolition Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nDemolition Work\nDemolition Work\nDemolition Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work","stage":"during_work","stage_basis":"heading","page":10},{"label":"D049","code":"D049","number":null,"title":"Security Fence","text":"A temporary security fence to WorkCover Authority requirements is to be provided to the property during the course of construction.\nNote: Fencing is not to be located on Council’s reserve area.","stage":"during_work","stage_basis":"heading","page":11},{"label":"D049","code":"D049","number":null,"title":"Security Fence","text":"A temporary security fence to WorkCover Authority requirements is to be provided to the property during the course of construction.\nNote: Fencing is not to be located on Council’s reserve area.","stage":"during_work","stage_basis":"heading","page":11},{"label":"D055","code":"D055","number":null,"title":"Refuse Disposal","text":"Adequate refuse disposal methods and builders storage facilities shall be installed on the site. Builders’ wastes, materials or sheds are not to be placed on any property other\nthan that which this approval relates to.","stage":"during_work","stage_basis":"heading","page":11},{"label":"D061","code":"D061","number":null,"title":"Craning and Hoardings","text":"Lifting or craning materials over a public footway or roadway is not permitted unless a “B” class construction hoarding has been installed in compliance with work cover authority\nrequirements.","stage":"during_work","stage_basis":"heading","page":11},{"label":"D063","code":"D063","number":null,"title":"Craning and Hoardings","text":"If the work is likely to cause pedestrian or vehicular traffic in a public area to be obstructed or rendered inconvenient; or if craning of materials is to occur across a public or road\nreserve area, a separate Road Occupancy Certificate and/or Hoarding approval must be obtained from Liverpool City Council prior to undertaking the works.","stage":"during_work","stage_basis":"heading","page":11},{"label":"D070","code":"D070","number":null,"title":"Notification of Damage","text":"The applicant/ builder shall be responsible to report to the Council of any damage to Council’s footpath and road carriageway as a consequence of demolition or excavation or\nbuilding activities or delivery/ departure of materials associated with this site and maintained the area until completion of the construction activities. Arrangements to the\nsatisfaction of Council are to be made for making safe by temporary repairs to Council’s footpath and road carriageway until permanent restoration and repair can be organised\nwith Council at the applicant’s cost.","stage":"during_work","stage_basis":"heading","page":11},{"label":"D075","code":"D075","number":null,"title":"Demolition Inspections","text":"The following inspections are required to be undertaken by Council in relation to approved demolition works:\nTo book an inspection with Council, please call 1300 362 170.","stage":"during_work","stage_basis":"heading","page":11},{"label":"D076","code":"D076","number":null,"title":"Handling of asbestos during demolition","text":"While demolition work is being carried out, any work involving the removal of asbestos must comply with the following requirements:\nOnly an asbestos removal contractor who holds the required class of Asbestos Licence issued by SafeWork NSW must carry out the removal, handling and disposal of\nany asbestos material;\nAsbestos waste in any form must be disposed of at a waste facility licensed by the NSW Environment Protection Authority to accept asbestos waste; and\nAny asbestos waste load over 100kg (including asbestos contaminated soil) or 10m² or more of asbestos sheeting must be registered with the EPA online reporting tool\nWasteLocate.","stage":"during_work","stage_basis":"heading","page":11},{"label":"D077","code":"D077","number":null,"title":"Site maintenance","text":"While demolition work is being carried out, the following requirements, as specified in the approved demolition management plan, must be\nmaintained until the demolition work and demolition waste removal are complete:\nProtective fencing and any hoardings to the perimeter on the site\nAccess to and from the site\nConstruction traffic management measures\nProtective measures for onsite tree preservation and trees in adjoining public domain\nOnsite temporary toilets\nA garbage container with a tightfitting lid","stage":"during_work","stage_basis":"heading","page":11},{"label":"D096","code":"D096","number":null,"title":"Disabled Access","text":"Access, parking and facilities for persons with disabilities to be provided in accordance with the provisions of the National Construction Code (NCC/BCA).","stage":"during_work","stage_basis":"heading","page":11},{"label":"D100","code":"D100","number":null,"title":"General Site Works Surface Contours","text":"Alterations to the natural surface contours must not impede or divert natural surface water runoff, so as to cause a nuisance to adjoining property owners.","stage":"during_work","stage_basis":"heading","page":11},{"label":"D105","code":"D105","number":null,"title":"General Site Works","text":"All roofwater is to be connected to an approved stormwater system.","stage":"during_work","stage_basis":"heading","page":11},{"label":"D110","code":"D110","number":null,"title":"General Site Works","text":"Stormwater pipeline connections to the street kerb shall be constructed in the following manner:","stage":"during_work","stage_basis":"heading","page":11},{"label":"D115","code":"D115","number":null,"title":"General Site Works Existing Hydrology","text":"Existing hydrological regimes shall be maintained so as not to negatively impact vegetation to be retained on site and downslope/downstream of the site.","stage":"during_work","stage_basis":"heading","page":11},{"label":"D120","code":"D120","number":null,"title":"General Site Works Runoff","text":"Any runoff entering the areas of vegetation to be retained shall be of an equivalent or better quality, and of a similar rate of flow to present levels.\nimmediately prior to the commencement of the demolition work, or handling of any building or structure that contains asbestos. The applicant shall also notify the\noccupants of the adjoining premises and Workcover NSW prior to the commencement of any works, Please note that demolition works are not permitted to commence\non site until such time as a satisfactory inspection result is obtained from Council, and\nimmediately following completion of the demolition. Please note that proof of appropriate disposal of demolition materials (including asbestos) may be required at this\ntime in accordance with the approved Waste Management Plan.\nthe kerb shall be sawcut on both sides of the proposed pipe outlet.\nan approved rectangular kerb adaptor shall be installed with the base matching the invert level of the gutter.\nthe kerb shall be reinstated to its original profile using a cement mortar containing an epoxy additive for adherence to the existing kerb.\n(a)\n(b)\n(a)\n(b)\n(c)\n11 Building Work\nBuilding Work\nDemolition Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nDemolition Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work","stage":"during_work","stage_basis":"heading","page":11},{"label":"D125","code":"D125","number":null,"title":"General Site Works Sediment","text":"The development, including construction, shall not result in any increase in sediment deposition into any water body, wetland, bushland or environmentally significant land.","stage":"during_work","stage_basis":"heading","page":12},{"label":"D130","code":"D130","number":null,"title":"Removal of dangerous and/or hazardous waste","text":"All dangerous and/or hazardous material must be removed by a suitably qualified and experienced contractor licensed by SafeWork NSW. The removal of such material must be\ncarried out in accordance with the requirements of SafeWork NSW and the material must be transported and disposed of in accordance with NSW Environment Protection\nAuthority requirements.","stage":"during_work","stage_basis":"heading","page":12},{"label":"D130","code":"D130","number":null,"title":"Removal of dangerous and/or hazardous waste","text":"All dangerous and/or hazardous material must be removed by a suitably qualified and experienced contractor licensed by SafeWork NSW. The removal of such material must be\ncarried out in accordance with the requirements of SafeWork NSW and the material must be transported and disposed of in accordance with NSW Environment Protection\nAuthority requirements.","stage":"during_work","stage_basis":"heading","page":12},{"label":"D140","code":"D140","number":null,"title":"Car Parking Areas","text":"Car parking spaces and driveways must be constructed of a minimum two coat finish seal or better.\nAll parking spaces must be clear of obstructions and columns, permanently line marked and provided with adequate manoeuvring facilities.\nThe design of these spaces must comply with Council’s DCP 2008, and Australian Standard 2890.1 Parking Facilities - OffStreet Car Parking.\nAll car parking areas are to be appropriately line marked and sign posted in accordance with the Council approved stamped plans.\nAll customer/visitor/staff parking areas are to be clearly signposted limiting car parking for customers/visitors/staff only. The applicant is to cover the costs of installation and\nmaintenance of the signage.\nThe onsite parking spaces shown in the approved plans must be identified in accordance with A.S.2890.1 Parking Facilities - OffStreet Car Parking.","stage":"during_work","stage_basis":"heading","page":12},{"label":"D146","code":"D146","number":null,"title":"Directional Signage","text":"Directional signage indicating the location of customer parking, “in” and “out”, crossings and directional arrows are to be provided in accordance with the Council approved\nstamped plans.","stage":"during_work","stage_basis":"heading","page":12},{"label":"D165","code":"D165","number":null,"title":"Public Domain Works","text":"All works within the road reserve, including the approved sign and line making scheme, are to be carried out by the applicant, at no cost to Council, in accordance with the\nTfNSW/RMS ‘Delineation Guidelines’.","stage":"during_work","stage_basis":"heading","page":12},{"label":"D180","code":"D180","number":null,"title":"Waste management","text":"While site work is being carried out:\nall waste management must be undertaken in accordance with the waste management plan; and\nupon disposal of waste, records of the disposal must be compiled and provided to principal certifier, detailing the following:\nThe contact details of the person(s) who removed the waste;\nThe waste carrier vehicle registration;\nThe date and time of waste collection;\nA description of the waste (type of waste and estimated quantity) and whether the waste is to be reused, recycled or go to landfill;\nThe address of the disposal location(s) where the waste was taken;\nThe corresponding tip docket/receipt from the site(s) to which the waste is transferred, noting date and time of delivery, description (type and quantity) of waste.\nIf waste has been removed from the site under an EPA Resource Recovery Order or Exemption, records in relation to that Order or Exemption must be maintained and provided\nto the principal certifier and Council.","stage":"during_work","stage_basis":"heading","page":12},{"label":"D180","code":"D180","number":null,"title":"Waste management","text":"While site work is being carried out:\nall waste management must be undertaken in accordance with the waste management plan; and\nupon disposal of waste, records of the disposal must be compiled and provided to principal certifier, detailing the following:\nThe contact details of the person(s) who removed the waste;\nThe waste carrier vehicle registration;\nThe date and time of waste collection;\nA description of the waste (type of waste and estimated quantity) and whether the waste is to be reused, recycled or go to landfill;\nThe address of the disposal location(s) where the waste was taken;\nThe corresponding tip docket/receipt from the site(s) to which the waste is transferred, noting date and time of delivery, description (type and quantity) of waste.\nIf waste has been removed from the site under an EPA Resource Recovery Order or Exemption, records in relation to that Order or Exemption must be maintained and provided\nto the principal certifier and Council.","stage":"during_work","stage_basis":"heading","page":12},{"label":"D240","code":"D240","number":null,"title":"Vegetation Weeds","text":"No known environmental weeds or known invasive plant species shall be included in the landscaping or revegetation. Hygiene practices shall be employed to avoid the spread of\ninvasive plants.","stage":"during_work","stage_basis":"heading","page":12},{"label":"D250","code":"D250","number":null,"title":"Vegetation Mulch","text":"Mulch generated from exotic trees or other weed species cleared shall not be used on site. It shall be removed from the site and disposed of appropriately and in accordance\nwith legislative requirements.","stage":"during_work","stage_basis":"heading","page":12},{"label":"D255","code":"D255","number":null,"title":"Vegetation Imported Soil or Mulch","text":"Any imported soil and/or mulch shall be free of contaminants, seed and propagules of weeds and undesirable species. Mulch shall not be used on flood liable land.","stage":"during_work","stage_basis":"heading","page":12},{"label":"D330","code":"D330","number":null,"title":"Switchboards","text":"Switchboards for utilities shall not be attached to the street and/or road elevations of the development.","stage":"during_work","stage_basis":"heading","page":12},{"label":"D335","code":"D335","number":null,"title":"External Lighting","text":"Any external lighting is to incorporate full cutoff shielding and is to be mounted so as to not cause any glare or spill over light nuisance within the development, neighbouring\nproperties or road users.","stage":"during_work","stage_basis":"heading","page":12},{"label":"D335","code":"D335","number":null,"title":"External Lighting","text":"12 Building Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nDemolition Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nAny external lighting is to incorporate full cutoff shielding and is to be mounted so as to not cause any glare or spill over light nuisance within the development, neighbouring\nproperties or road users.","stage":"during_work","stage_basis":"heading","page":12},{"label":"D340","code":"D340","number":null,"title":"Glass Reflectivity","text":"The reflectivity index of glass used in the external facade of the building is not to exceed 20%.","stage":"during_work","stage_basis":"heading","page":13},{"label":"D360","code":"D360","number":null,"title":"Graffiti","text":"A graffiti resistant coating shall be applied to any fences or structures that have frontage to a public area, for example a roadway, public reserve etc.","stage":"during_work","stage_basis":"heading","page":13},{"label":"D426","code":"D426","number":null,"title":"Soil management","text":"While site work is being carried out, the principal certifying authority must be satisfied all soil removed from or imported to the site is managed in\naccordance with the following requirements:\nAll excavated material removed from the site must be classified in accordance with the EPA’s Waste Classification Guidelines before it is disposed of at an approved\nwaste management facility and the classification and the volume of material removed must be reported to the principal certifying authority.\nAll fill material imported to the site must be:\nVirgin Excavated Natural Material as defined in Schedule 1 of the Protection of the Environment Operations Act 1997 ; or\na material identified as being subject to a resource recovery exemption by the NSW EPA; or\na combination of Virgin Excavated Natural Material as defined in Schedule 1 of the Protection of the Environment Operations Act 1997 and a material identified as\nbeing subject to a resource recovery exemption by the NSW EPA.","stage":"during_work","stage_basis":"heading","page":13},{"label":"D430","code":"D430","number":null,"title":"Unidentified Contamination","text":"Any new information which arises during remediation, demolition or construction works that has the potential to alter previous conclusions about site contamination and\nremediation must be immediately notified in writing to the certifier and Liverpool City Council.\nA section 4.55 Application under the Environmental Planning and Assessment Act 1979 must be made for any proposed works outside the scope of the approved development\nconsent.","stage":"during_work","stage_basis":"heading","page":13},{"label":"D445","code":"D445","number":null,"title":"Air Quality","text":"Dust screens shall be erected and maintained in good repair around the perimeter of the subject land during land clearing, demolition, and construction works.","stage":"during_work","stage_basis":"heading","page":13},{"label":"D450","code":"D450","number":null,"title":"Air Quality","text":"During construction where operations involve excavation, filling or grading of land, or removal of vegetation, including ground cover, the consent holder is to ensure dust is\nsuppressed by regular watering until such time as the soil is stabilised to prevent airborne dust transport. Where wind velocity exceeds five knots the Principal Certifier may\ndirect that work is not to proceed.","stage":"during_work","stage_basis":"heading","page":13},{"label":"D455","code":"D455","number":null,"title":"Dropped Edge Beam","text":"The proposed concrete slab construction must incorporate drop edge beams to ensure any fill is adequately retained within the envelope of the building. The external masonry\nwall shall extend from the concrete beam at natural ground level.","stage":"during_work","stage_basis":"heading","page":13},{"label":"D460","code":"D460","number":null,"title":"Salinity","text":"The development shall be carried out in accordance with ‘Appendix B’ of the Liverpool Growth Precincts Development Control Plan 2013.\nThe development shall be carried out in accordance with Part 1, Section 11 ‘Salinity Risk’ of the Liverpool Development Control Plan 2008.","stage":"during_work","stage_basis":"heading","page":13},{"label":"D465","code":"D465","number":null,"title":"Air Conditioning","text":"The plant associated with any air conditioning system shall not cause any offensive noise as defined under the Protection of the Environment Operations Act 1997.","stage":"during_work","stage_basis":"heading","page":13},{"label":"D475","code":"D475","number":null,"title":"Imported Fill Material","text":"During construction the consent holder is to ensure fill imported on to the site is be compatible with the existing soil characteristic for site drainage purposes.","stage":"during_work","stage_basis":"heading","page":13},{"label":"D552","code":"D552","number":null,"title":"Implementation of the site management plans","text":"While site work is being carried out:\nthe measures required by the construction site management plan and the erosion and sediment control plan (plans) must be implemented at all times; and\na copy of these plans must be kept on site at all times and made available to Council officers upon request.","stage":"during_work","stage_basis":"heading","page":13},{"label":"D552","code":"D552","number":null,"title":"Implementation of the site management plans","text":"While site work is being carried out:\nthe measures required by the construction site management plan and the erosion and sediment control plan (plans) must be implemented at all times; and\na copy of these plans must be kept on site at all times and made available to Council officers upon request.","stage":"during_work","stage_basis":"heading","page":13},{"label":"D553","code":"D553","number":null,"title":"Erosion & Sediment Control","text":"Erosion and sediment control measures shall remain in place and be maintained until all disturbed areas have been rehabilitated and stabilised. All disturbed areas shall be\nprogressively stabilised and/or revegetated so that no areas remain exposed to potential erosion damage for a period of greater than 14 days.","stage":"during_work","stage_basis":"heading","page":13},{"label":"D554","code":"D554","number":null,"title":"Erosion & Sediment Control","text":"The developer is to maintain all adjoining public roads to the site in a clean and tidy state, free of excavated “spoil” material.","stage":"during_work","stage_basis":"heading","page":13},{"label":"D555","code":"D555","number":null,"title":"Erosion Control Maintenance","text":"Sediment and erosion control measures are to be adequately maintained during the works until the establishment of grass.","stage":"during_work","stage_basis":"heading","page":13},{"label":"D560","code":"D560","number":null,"title":"Erosion Control","text":"13 Building Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nDemolition Work\nBuilding Work\nBuilding Work\nVehicular access to the site shall be controlled through the installation of wash down bays or shaker ramps to prevent tracking of sediment or dirt onto adjoining roadways.\nWhere any sediment is deposited on adjoining roadways is shall be removed by means other than washing. All material is to be removed as soon as possible and the collected\nmaterial is to be disposed of in a manner which will prevent its mobilisation.","stage":"during_work","stage_basis":"heading","page":13},{"label":"D565","code":"D565","number":null,"title":"Water Quality","text":"During construction the consent holder is to ensure all topsoil, sand, aggregate, spoil or any other material that can be moved by water is stored clear of any drainage line,\neasement, water body, stormwater drain, footpath, kerb or road surface.","stage":"during_work","stage_basis":"heading","page":14},{"label":"D570","code":"D570","number":null,"title":"Pollution Control Site Operations","text":"During construction, building operations including but not limited to brick cutting, mixing mortar and the washing of tools, paint brushes, formwork, concrete trucks and the like\nmust not be performed on the public footway or any other locations which may lead to the discharge of materials into Council’s stormwater drainage system.","stage":"during_work","stage_basis":"heading","page":14},{"label":"D574","code":"D574","number":null,"title":"Pollution Control Truck Movements","text":"The loading and unloading of all vehicles associated with the development must be undertaken within the property boundary of the premises subject to this consent.\nMeasures must be implemented to prevent tracking of sediment by vehicles onto roads.\nVehicle loads must be covered when entering and exiting the site with material.","stage":"during_work","stage_basis":"heading","page":14},{"label":"D578","code":"D578","number":null,"title":"Ventilation","text":"The premises shall be ventilated in accordance with the requirements of the BCA (if using deemed to satisfy provisions: AS 1668, Parts 1 & 2).","stage":"during_work","stage_basis":"heading","page":14},{"label":"D582","code":"D582","number":null,"title":"Aboriginal Cultural Heritage Staff and Contractors","text":"All relevant onsite staff and contractors should be made aware of their statutory obligations for heritage under NSW National Parks and Wildlife Act 1974 and the\nNSW Heritage Act 1977. They are to be informed of what the potential heritage on the site will be and its significance. The site supervisor is to maintain a record of who has\ncompleted the heritage induction and this is to be provided to Council prior to Issue of Occupation Certificate.","stage":"during_work","stage_basis":"heading","page":14},{"label":"D583","code":"D583","number":null,"title":"Aboriginal Cultural Heritage Unexpected Finds","text":"As required by the National Parks and Wildlife Service Act 1974 and the Heritage Act 1977, in the event that Aboriginal cultural heritage or historical cultural fabric or deposits\nare encountered/discovered where they are not expected, works must cease immediately and Council and the Heritage Division of the Office of Environment and Heritage (OEH)\nmust be notified of the discovery.\nIn the event that archaeological resources are encountered, further archaeological work may be required before works can recommence, including the statutory requirement\nunder the Heritage Act 1977 to obtain the necessary approvals/permits from the Heritage Division of the OEH.\nNote: The National Parks and Wildlife Service Act 1974 and the Heritage Act 1977 impose substantial penalty infringements and / or imprisonment for the unauthorised\ndestruction of archaeological resources, regardless of whether or not such archaeological resources are known to exist on the site.","stage":"during_work","stage_basis":"heading","page":14},{"label":"D584","code":"D584","number":null,"title":"Skeletal Remains","text":"In the event that skeletal remains are uncovered, work must cease immediately in that area and the area secured. NSW Police must be contacted and no further action taken\nuntil written advice has been provided by the NSW Police. If the remains are determined to be of Aboriginal origin, the Office of Environment and Heritage must be notified by\nringing the Enviroline 131 555 and a management plan prior to works recommencing must be developed in consultation with relevant Aboriginal stakeholders.","stage":"during_work","stage_basis":"heading","page":14},{"label":"D590","code":"D590","number":null,"title":"Public Domain Works Street Lighting","text":"Street lights are to be installed in accordance with the Endeavour Energy certified plans to their satisfaction.","stage":"during_work","stage_basis":"heading","page":14},{"label":"D596","code":"D596","number":null,"title":"Drainage Connection","text":"Prior to the connection of private drainage to Council’s drainage system, an inspection is to be carried out by Liverpool City Council’s Development Engineering Unit. A fee will\nbe charged in accordance with Council’s adopted Fees and Charges, and is to be paid prior to the inspection.","stage":"during_work","stage_basis":"heading","page":14},{"label":"D597","code":"D597","number":null,"title":"Major Filling/ Earthworks","text":"All earthworks shall be undertaken in accordance with AS 3798 and Liverpool City Council’s Design Guidelines and Construction Specification for Civil Works.\nThe level of testing shall be determined by the Geotechnical Testing Authority/ Superintendent in consultation with the Principal Certifying Authority.","stage":"during_work","stage_basis":"heading","page":14},{"label":"D600","code":"D600","number":null,"title":"Correct waste separation and removal","text":"All demolition, excavation and construction wastes must be separated as they are generated and kept in separate spoil piles, bays, builder’s skips and/or site bins. No wastes\nother than those noted on the approved waste management plan as being reused on site, are to be left on site after the completion of the works.","stage":"during_work","stage_basis":"heading","page":14},{"label":"D605","code":"D605","number":null,"title":"Containment of site wastes during building","text":"All demolition, excavation or construction wastes, e.g. wrapping, packaging materials, bags, insulation, sand, soil etc., must be kept fully enclosed at all times to prevent them\nfrom becoming displaced in strong wind conditions or from washing into sewers, storm drains or creeks, or onto adjacent properties or public land during wet weather.","stage":"during_work","stage_basis":"heading","page":14},{"label":"D605","code":"D605","number":null,"title":"Containment of site wastes during building","text":"All demolition, excavation or construction wastes, e.g. wrapping, packaging materials, bags, insulation, sand, soil etc., must be kept fully enclosed at all times to prevent them\nfrom becoming displaced in strong wind conditions or from washing into sewers, storm drains or creeks, or onto adjacent properties or public land during wet weather.","stage":"during_work","stage_basis":"heading","page":14},{"label":"D655","code":"D655","number":null,"title":"Noise and Vibration requirements","text":"While site work is being carried out, noise generated from the site must not exceed an LAeq (15 min) of <5dB/ INSERT LESS THAN 5dB>(A) above background noise, when\nmeasured at a lot boundary of the site.","stage":"during_work","stage_basis":"heading","page":14},{"label":"D660","code":"D660","number":null,"title":"Construction Noise and Vibration","text":"Noise and vibration associated with excavation, demolition and construction activities shall comply with the management levels detailed within the ‘Interim Construction Noise\nGuideline’ published by the Department of Environment and Climate Change NSW (DECC 2009/265) dated July 2009 and acceptable vibration values prescribed within the\nEnvironmental Noise Management Assessing Vibration: A Technical Guideline (Department of Environment and Conservation, 2006).\n14 Building Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nAll feasible and reasonable noise and vibration mitigation measures shall be implemented and any activities which may exceed the construction noise management levels and\nvibration criteria shall be identified and managed in accordance with the approved Construction Environmental Management Plan (CEMP).","stage":"during_work","stage_basis":"heading","page":14},{"label":"D664","code":"D664","number":null,"title":"Contamination","text":"The development, including all civil works and demolition, must comply with the requirements of the Contaminated Land Management Act 1997, State Environmental Planning\nPolicy (Resilience and Hazards) 2021, Chapter 4, and Managing Land Contamination - Planning Guidelines (Planning NSW/EPA 1998).","stage":"during_work","stage_basis":"heading","page":15},{"label":"D666","code":"D666","number":null,"title":"Record Keeping of Imported Fill","text":"Records of the following must be submitted to the principal certifying authority monthly and at the completion of earth works:\nThe course (including the address and owner of the source site), nature and quantity of all incoming loads including the date, the name of the carrier, and the vehicle\nregistration;\nThe results of a preliminary contamination assessment carried out on any fill material used in the development.\nThe results of any chemical testing of fill material.","stage":"during_work","stage_basis":"heading","page":15},{"label":"D668","code":"D668","number":null,"title":"Traffic Management","text":"Applications must be made to Council’s Traffic & Transport Section for any road closures. The applicant is to include a Traffic Control Plan, prepared by a suitably qualified\nperson, which is to include the date and times of closures and any other relevant information.","stage":"during_work","stage_basis":"heading","page":15},{"label":"D950","code":"D950","number":null,"title":"Mailboxes","text":"The mailboxes are to be consistent with the design and colours and materials for the development.","stage":"during_work","stage_basis":"heading","page":15},{"label":"D951","code":"D951","number":null,"title":"External bathroom, WC and ensuite windows","text":"The windows of all bathrooms, W.C. and ensuites shall be fitted with translucent obscure glazing to the satisfaction of the PCA.","stage":"during_work","stage_basis":"heading","page":15},{"label":"D952","code":"D952","number":null,"title":"Vegetation and Landscaping","text":"Premium quality organic garden soil shall be incorporated into all planting areas in sufficient quantity to achieve optimum plant growing\nconditions.","stage":"during_work","stage_basis":"heading","page":15},{"label":"D953","code":"D953","number":null,"title":"Waste Storage Area","text":"Any bin bays must be:\n(a) Provided with mechanical ventilation;\n(b) Provided with a hose cock for hosing the garbage bin bay and a sewered drainage point in or adjacent to the bin storage area. The drainage point should have a fine grade\ndrain cover sufficient to prevent coarse pollutants from entering the sewer. If the hose cock is located inside the bin storage bay, it is not to protrude into the space indicated for\nthe placement of bins;\n(c) Provided with sufficient light to permit usage at night;\n(d) Allocated with sufficient space within the bin bay to allow for access to all required bins by residents and waste collectors, as well as manoeuvring of bins within the bay and\nfor the removal and return of bins by the waste collector;\n(e) Provided with signage to be prominently displayed in each bin bay, or waste service room, as appropriate indicating that:\n(i)Garbage is to be placed wholly within the garbage bins provided;\n(ii)Only recyclable materials accepted by Council are to be placed within the recycling bins;\n(iii)The area is to be kept tidy;\n(iv)A phone number to be displayed for arranging disposal of bulky items;\n(v)50% of all messages are to be displayed using graphic illustrative content;\n(vi)Bin bay signs are available from Council;\n(vii)Signage on how to use any garbage chutes is to be located prominently next to the chute;\n(viii)Operation, maintenance and cleaning of the garbage compactor and associated equipment is the responsibility of the strata management or body corporate, and not of\nCouncil;\n(ix)Maximum compaction ratio is 2:1;\n(x)Operation, maintenance and cleaning of the garbage chutes and associated waste cupboards, rooms, or equipment is the responsibility of the strata management or body\ncorporate, and not of Council.","stage":"during_work","stage_basis":"heading","page":15},{"label":"E003","code":"E003","number":null,"title":"Worksasexecuted plans and any other documentary evidence","text":"Before the issue of an Occupation Certificate, worksasexecuted plans, any compliance certificates and any other evidence confirming the\nfollowing completed works must be submitted to the satisfaction of the principal certifier:\nAll stormwater drainage systems and storage systems; and\nThe matters that Council require to be documented\nA copy of the plans must be provided to Council with the Occupation Certificate","stage":"before_oc","stage_basis":"heading","page":15},{"label":"E005","code":"E005","number":null,"title":"Certificates","text":"The premises must not be occupied until an Occupation Certificate (OC) is issued by the certifier. Copies of all documents relied upon for the issue of the OC must be attached\nto the OC and registered with Council.","stage":"before_oc","stage_basis":"heading","page":15},{"label":"E010","code":"E010","number":null,"title":"Certificates","text":"All required documentary evidence for the critical stage inspections carried out prior, during and at the completion of construction, must be submitted to Council together with\nthe required registration fee payment.","stage":"before_oc","stage_basis":"heading","page":15},{"label":"E016","code":"E016","number":null,"title":"Retaining Walls","text":"The construction of the retaining wall/s shown on the approved plans must be completed to the satisfaction of the Principal Certifier, prior to the release of the Whole Occupation\nCertificate.\nThe required retaining walls shall be completed within 3 months of the initial occupation of the building or part of the building.","stage":"before_oc","stage_basis":"heading","page":15},{"label":"E020","code":"E020","number":null,"title":"Acoustic Report","text":"Confirmation in writing that the recommended measures were incorporated as required by the report.\n15 Building Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work","stage":"before_oc","stage_basis":"heading","page":15},{"label":"E026","code":"E026","number":null,"title":"Removal of waste upon completion","text":"","stage":"before_oc","stage_basis":"heading","page":16},{"label":"E030","code":"E030","number":null,"title":"Section 73 Sydney Water Certificate","text":"A Section 73 Compliance Certificate under the Sydney Water Act 1994 must be obtained and submitted to the Principal Certifier prior to issue of Occupation Certificate.","stage":"before_oc","stage_basis":"heading","page":16},{"label":"E033","code":"E033","number":null,"title":"Cladding","text":"Prior to issuing an occupation certificate the principal certifier must be satisfied that suitable evidence has been provided to demonstrate that the external wall cladding material\nand system is consistent with the consent documentation, BCA and relevant Australian Standards.","stage":"before_oc","stage_basis":"heading","page":16},{"label":"E035","code":"E035","number":null,"title":"Completion of public utility services","text":"Before the issue of the relevant occupation certificate, confirmation must be obtained from the relevant authority that any adjustment or augmentation of any public utility\nservices including gas, water, sewer, electricity, street lighting and telecommunications, required as a result of the development, have been completed and this confirmation\nmust be provided to the principal certifier.","stage":"before_oc","stage_basis":"heading","page":16},{"label":"E037","code":"E037","number":null,"title":"Liverpool City Council clearance Roads Act/ Local Government Act","text":"Prior to the issue of an Occupation Certificate, the Principal Certifying Authority shall ensure that all works associated with a S138 Roads Act approval or S68 Local\nGovernment Act approval have been inspected and signed off by Liverpool City Council.","stage":"before_oc","stage_basis":"heading","page":16},{"label":"E050","code":"E050","number":null,"title":"Display of Street Numbers","text":"Street numbers must be prominently displayed at the front of the development in a contrasting colour to the building materials and at the front of each individual unit to comply\nwith the Local Government Act 1973, Section 124(8). The number should be a minimum height of 120mm and be visible at night.","stage":"before_oc","stage_basis":"heading","page":16},{"label":"E060","code":"E060","number":null,"title":"BASIX","text":"Supporting documentation issued by a suitable qualified person who has installed or carried out the works associated with the BASIX commitments shall be submitted to the\nPrincipal Certifier.","stage":"before_oc","stage_basis":"heading","page":16},{"label":"E064","code":"E064","number":null,"title":"Completion of landscape and tree works","text":"Before the issue of an Occupation Certificate, the principal certifier must be satisfied all landscape and treeworks have been completed in accordance with approved plans and\ndocuments and any relevant conditions of this consent.","stage":"before_oc","stage_basis":"heading","page":16},{"label":"E065","code":"E065","number":null,"title":"Landscaping","text":"Upon completion of the approved landscape works associated with the development and prior to the issue of any Occupation Certificate, an Implementation Report is to be\nsubmitted to the Principal Certifier attesting to the satisfactory completion of the landscape works in accordance with the approved landscape plan. The report is to be prepared\nby a suitably qualified person.","stage":"before_oc","stage_basis":"heading","page":16},{"label":"E075","code":"E075","number":null,"title":"Road Works","text":"All redundant vehicular crossings shall be removed and replaced with Council’s standard kerb and gutter at no cost to Council. The removal and replacement of a standard\ndriveway with standard integral kerb and gutter shall be subject of a driveway application to Council and works supervised by that driveway inspection process.","stage":"before_oc","stage_basis":"heading","page":16},{"label":"E080","code":"E080","number":null,"title":"Waste Collection Secondary Dwelling","text":"Prior to the issue of an occupation certificate, a full domestic waste service is required to be provided to the secondary dwelling. This can be arranged by contacting Liverpool\nCity Council on 1300 362 170.","stage":"before_oc","stage_basis":"heading","page":16},{"label":"E100","code":"E100","number":null,"title":"Design Verification Statement","text":"In accordance with the Environmental Planning and Assessment Regulation 2000 and State Environmental Planning Policy (SEPP) 65 “Design Quality of Residential Flat\nDevelopment”, the subject development must be undertaken or directed by a ‘qualified designer’ (i.e., a registered architect under the Architects Act). In this regard, a design\nverification statement shall be submitted to the Principle Certifier (PC) assessing the development, upon completion of all works subject of this consent and its accompanying\nCC. The PC shall ensure that the statement prepared by the qualified designer provides the following:","stage":"before_oc","stage_basis":"heading","page":16},{"label":"E108","code":"E108","number":null,"title":"Residential Car Park","text":"Before the issue of an occupation certificate the principal certifier must be satisfied that the proposed garage/security door fitted to the underground car parking entrance must\nbe independently mounted on rubber pads or otherwise installed to prevent noise and the transmission of noise and vibration through the concrete walls and/or columns.","stage":"before_oc","stage_basis":"heading","page":16},{"label":"E245","code":"E245","number":null,"title":"Construction and installation of ventilation system","text":"Before the issue of an occupation certificate, a suitably qualified person must provide details demonstrating compliance to the principal certifier which demonstrates that the\nmechanical exhaust ventilation system has been constructed and installed in accordance with the approved plans.","stage":"before_oc","stage_basis":"heading","page":16},{"label":"E250","code":"E250","number":null,"title":"Mechanical Ventilation Certification","text":"Upon completion of works and before the issue of any occupation certificate, a Mechanical Ventilation Certificate of Completion and Performance prepared by a professional\nengineer or other suitably qualified person must be submitted to certifier for their review and approval. The certification must be accompanied by details of the tests carried out in\nrelation to ventilation and acoustics and confirm that the systems comply with the approved plans, specifications, Building Code of Australia and Australian Standard AS 1668\nParts 1 and 2.","stage":"before_oc","stage_basis":"heading","page":16},{"label":"E272","code":"E272","number":null,"title":"Trade Waste Agreement for Vehicle Wash Bay/s","text":"All vehicle washing is to be conducted in the designated vehicle wash bay/s which shall be connected to the sewer. The discharge of trade wastewater is to be approved by\nSydney Water via a permit or written agreement. No wash water or trade wastewater is to enter the stormwater or creek systems.\nBefore the issue of any occupation certificate, copies of the plumber’s certificate of compliance and the Trade Waste Agreement issued by Sydney Water for installation of the\noil/water separator must be submitted to the certifier.","stage":"before_oc","stage_basis":"heading","page":16},{"label":"E320","code":"E320","number":null,"title":"Secure Mailboxes","text":"a valid and current chartered architect’s certificate number (as issued by the Board of Architects of NSW), and\nthat the completed development achieves the design quality of the development as shown in the plans and specifications submitted and approved with the CC, having\nregard to the design principles set out in Part 2 of SEPP 65.\n(a)\n(b)\n16 Building Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nMailboxes must be recessed into the building or only accessible from the foyer of the building. A CCTV camera system must be installed providing continuous surveillance of\nthe mailbox area.","stage":"before_oc","stage_basis":"heading","page":16},{"label":"E400","code":"E400","number":null,"title":"Stormwater Compliance","text":"Prior to the issue of an Occupation Certificate, the Principal Certifying Authority shall ensure that the:\nHave been satisfactorily completed in accordance with the approved Construction Certificate and the requirements of this consent,\nHave met the design intent with regard to any construction variations to the approved design, and\nAny remedial works required to been undertaken have been satisfactorily completed.\nDetails of the approved and constructed system/s shall be provided as part of the WorksAsExecuted drawings.","stage":"before_oc","stage_basis":"heading","page":17},{"label":"E404","code":"E404","number":null,"title":"Restriction as to User and Positive Covenant","text":"Prior to the issue of an Occupation Certificate a restriction as to user and positive covenant relating to the following shall be registered on the title\nof the property:\nThe restriction as to user and positive covenant shall be in Liverpool City Council’s standard wording as detailed in Liverpool City Council’s Design and Construction Guidelines\nand Construction Specification for Civil Works.","stage":"before_oc","stage_basis":"heading","page":17},{"label":"E407","code":"E407","number":null,"title":"Repair of infrastructure","text":"","stage":"before_oc","stage_basis":"heading","page":17},{"label":"E408","code":"E408","number":null,"title":"Rectification of Damage","text":"Prior to the issue of an Occupation Certificate, any damage to Council infrastructure not identified in the dilapidation report, as a result of the\ndevelopment shall be rectified at no cost to Liverpool City Council.\nAny rectification works within Mckay Avenue will require a Roads Act application. The application is to be submitted and approved by Liverpool City Council prior to such works\ncommencing.","stage":"before_oc","stage_basis":"heading","page":17},{"label":"E416","code":"E416","number":null,"title":"Linemarking & Signage","text":"Prior to the issue of an Occupation Certificate and installation of regulatory / advisory linemarking and signage, plans are to be lodged with Liverpool City Council and approved\nby the Local Traffic Committee.\nNote: Allow eight (8) weeks for approval by the Local Traffic Committee.","stage":"before_oc","stage_basis":"heading","page":17},{"label":"E420","code":"E420","number":null,"title":"Entry/ Exit Signage","text":"Prior to the issue of an Occupation Certificate signage which is clearly visible from the public road shall be placed within the development site.\nThe signage shall indicate that the ### vehicular access is to be used for ingress purposes only and appropriately signposted \"Entry Only\". The ### vehicular access is to be\nused for egress purposes only and appropriately signposted \"No Entry\".","stage":"before_oc","stage_basis":"heading","page":17},{"label":"E432","code":"E432","number":null,"title":"Footpaths","text":"Construction of 1.5m wide by 100mm thick (with one layer of SL72 reinforcing mesh) concrete path paving on one side of all residential access\nroads and both sides of all collector and distributor roads. Path paving will not be required in minor culdesac with less than fifteen lots.","stage":"before_oc","stage_basis":"heading","page":17},{"label":"E436","code":"E436","number":null,"title":"Dilapidation Report","text":"Any rectification works required by Council regarding the condition of Council infrastructure shall be undertaken, at full cost to the developer.","stage":"before_oc","stage_basis":"heading","page":17},{"label":"E950","code":"E950","number":null,"title":"Fire Safety Certificate","text":"A single and complete Fire Safety Certificate, certifying the installation and operation of all of the fire safety measures within the building must be\nsubmitted to Council with the Occupation Certificate.","stage":"before_oc","stage_basis":"heading","page":17},{"label":"E951","code":"E951","number":null,"title":"Rock Anchors","text":"Upon completion of works, any rock anchors used during construction shall be completely destressed or removed without damage to Council’s\nassets or to existing utility services. Proof shall be provided in the form of certification from the Qualified Structural or Geotechnical Engineer prior to the issue of an Occupation\nCertificate.","stage":"before_oc","stage_basis":"heading","page":17},{"label":"E952","code":"E952","number":null,"title":"Stormwater Devices","text":"The Operation and Maintenance Manual for the stormwater devices shall be submitted to Council.","stage":"before_oc","stage_basis":"heading","page":17},{"label":"E953","code":"E953","number":null,"title":"Basement Pump Out System","text":"A certificate of compliance for the pump out drainage system of the basement level shall be issued to the Principal Certifier by the pump\ninstallers stating that the pump out system has been installed to operate in accordance with the Council requirements and the approved drawings.","stage":"before_oc","stage_basis":"heading","page":17},{"label":"E954","code":"E954","number":null,"title":"Basement Pump Out System","text":"A maintenance schedule for the stormwater drainage basement pump out system including a sketch plan of the components forming the system\nshall be submitted to Council.","stage":"before_oc","stage_basis":"heading","page":17},{"label":"G060","code":"G060","number":null,"title":"Graffiti","text":"Onsite detention system/s,\nBasement Carpark pumpout system:\nOnsite detention system/s,\nBasement Carpark pumpout system:\n(a)\n(b)\n(a)\n(b)\n17 Building Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nBuilding Work\nDuring ongoing use of the premises, ensure graffiti is removed from the exterior of the building or associated structures, including any fences, site services and retaining/planter\nbed walls.","stage":"ongoing","stage_basis":"heading","page":17},{"label":"G065","code":"G065","number":null,"title":"Unreasonable Noise and Vibration","text":"The use of the premises and/or machinery equipment installed must not give rise to offensive noise so as to interfere with the amenity of the neighbouring properties.\nShould an offensive noise complaint be received by Liverpool City Council, an acoustic assessment must be undertaken by a suitably qualified acoustic consultant and an\nacoustic report must be submitted to Liverpool City Council for review. Any noise attenuation recommendations approved by Liverpool City Council must be implemented and\nthen assessed and certified in writing by a suitably qualified acoustic consultant to verify conformance with the requirements of the aforementioned acoustic report.\nNote: The ‘suitably qualified acoustic consultant’ must be a member of the Australian Acoustical Society or employed by an Association of Australasian Acoustical Consultants\n(AAAC) member firm.","stage":"ongoing","stage_basis":"heading","page":18},{"label":"G090","code":"G090","number":null,"title":"Maintenance of wastewater and stormwater treatment device","text":"During occupation and ongoing use of the building, all wastewater and stormwater treatment devices (including drainage systems, sumps and traps, and onsite detention) must\nbe regularly maintained to remain effective and in accordance with any positive covenant (if applicable).","stage":"ongoing","stage_basis":"heading","page":18},{"label":"G100","code":"G100","number":null,"title":"Waste Collection and Management","text":"Waste and recyclable material must be managed in a satisfactory manner, covered at all times and not give rise to offensive odour or encourage pest activity. All solid and liquid\nwaste must be removed regularly from the site by a registered waste contractor. Waste must not be permitted to accumulate near the waste storage bins.","stage":"ongoing","stage_basis":"heading","page":18},{"label":"G130","code":"G130","number":null,"title":"Waste Storage Area","text":"Waste bins must be stored in designated garbage/ trade refuse areas, which must be kept tidy at all times. Bins must not be stored or allowed to overflow in parking or\nlandscaping areas, must not obstruct the exit of the building, and must not leave the site onto neighbouring public or private properties.","stage":"ongoing","stage_basis":"heading","page":18},{"label":"G190","code":"G190","number":null,"title":"Parking Spaces Assessment Planner","text":"The following parking spaces should be used solely for the purpose it has been provided.\nUnrestricted resident car parking","stage":"ongoing","stage_basis":"heading","page":18},{"label":"G210","code":"G210","number":null,"title":"Car Parking Management","text":"All parking areas shown on the approved plans must be used solely for this purpose.","stage":"ongoing","stage_basis":"heading","page":18},{"label":"G220","code":"G220","number":null,"title":"Loading Areas","text":"All loading and unloading must take place from the designated loading dock/bay. This area is to be clearly marked/signposted for use by delivery vehicles only.","stage":"ongoing","stage_basis":"heading","page":18},{"label":"G230","code":"G230","number":null,"title":"Vehicle Access","text":"Vehicles entering or leaving the development site should be in forward direction.","stage":"ongoing","stage_basis":"heading","page":18},{"label":"G345","code":"G345","number":null,"title":"Lighting","text":"Illumination of the site must be arranged in accordance with the requirements and specifications of AS 4282:2019 Control of obtrusive effects of outdoor lighting so as not to\nimpact upon the amenity of the occupants of adjoining and nearby premises.","stage":"ongoing","stage_basis":"heading","page":18},{"label":"G347","code":"G347","number":null,"title":"External lighting during ongoing use","text":"During ongoing use of the premises, all lighting must be operated and maintained in accordance with the approved plans and the requirements of this consent.","stage":"ongoing","stage_basis":"heading","page":18},{"label":"G360","code":"G360","number":null,"title":"Noise Silent Building Intruder Alarm System","text":"Any building intruder alarm installed at the site must be a “silent back to base” type.","stage":"ongoing","stage_basis":"heading","page":18},{"label":"G370","code":"G370","number":null,"title":"Use of building intruder alarm/s","text":"Any building intruder alarm/s associated with the development must only be permitted to operate in accordance with Clause 42 of the Protection of the Environment Operations\n(Noise Control) Regulation 2017.","stage":"ongoing","stage_basis":"heading","page":18},{"label":"G410","code":"G410","number":null,"title":"Landscaping","text":"Landscaping shall be maintained in accordance with the approved plan, in a healthy state and in perpetuity by the existing or future owners and occupiers of the development.\nIf any of the vegetation comprising the landscaping dies or is removed, it is to be replaced with vegetation of the same species, and similar maturity as the vegetation which has\ndied or was removed.\nAn annual report shall be submitted to Council, for the 3 years following issue of the OC, certifying that the landscaping works have been satisfactorily maintained.","stage":"ongoing","stage_basis":"heading","page":18},{"label":"G468","code":"G468","number":null,"title":"Smokefree Requirements","text":"The requirements of the Smokefree Environment Act 2000 and Smokefree Environment Regulation 2016 must be complied with at all times.\nThis development consent does not imply that the development meets the requirements of the aforementioned legislation. In the event that the Applicant and/or Occupier wishes\nto facilitate smoking within the premises, they must ensure that the design and construction of the area proposed to facilitate smoking fully complies with the requirements of\nthe Smokefree Environment Act 2000 and Smokefree Environment Regulation 2016.","stage":"ongoing","stage_basis":"heading","page":18},{"label":"G767","code":"G767","number":null,"title":"Use of air conditioner/s on residential premises","text":"Any air conditioner/s used on the residential premises must comply with the requirements of the Protection of the Environment Operations (Noise Control) Regulation 2017 and\nmust not:\nemit noise that is audible within a habitable room in any other residential property (regardless of whether any door or window to that room is open):\ni. before 8:00am or after 10:00pm on any Saturday, Sunday or public holiday; or\nii. before 7:00am or after 10:00pm on any other day; or\ncause “offensive noise” as defined by the Protection of the Environment Operations Act 1997; or\nemit a sound pressure level as measured over a 15 minute period (LAeq (15 minute)) at the boundary of any other residential property, at a time other than those\nspecified in (i) and (ii) above, which exceeds the background (LA90 (15 minute)) by more than 5 dB(A).\n(a)\n(b)\n(c)\n18 Building Work(G768) Use of pump/s on residential premises\nAny pump/s used on the residential premises including but not limited to swimming pool pumps, spa pumps, solar water pumps, rainwater tank pumps and associated\nequipment must comply with the requirements of the Protection of the Environment Operations (Noise Control) Regulation 2017 and must not:\nemit noise that is audible within a habitable room in any other residential property (regardless of whether any door or window to that room is open):\ni. before 8:00am or after 8:00pm on any Saturday, Sunday or public holiday; or\nii. before 7:00am or after 8:00pm on any other day; or\ncause “offensive noise” as defined by the Protection of the Environment Operations Act 1997; or\nemit a sound pressure level as measured over a 15 minute period (LAeq (15 minute)) at the boundary of any other residential property, at a time other than those\nspecified in (i) and (ii) above, which exceeds the background (LA90 (15 minute)) by more than 5 dB(A).\n(a)\n(b)\n(c)\n19","stage":"ongoing","stage_basis":"heading","page":18}]});
